/// Returns the index of the maximum element in a non-empty `Vec<i8>`.
/// If the maximum value occurs multiple times, returns the leftmost index.
///
/// Precondition: `arr.len() > 0`.
fn argmax(arr: &Vec<i8>) -> usize {
    // Start with the first element as the current maximum.
    let mut best_idx: usize = 0;
    let mut best_val: i8 = arr[0];

    // Scan left-to-right; only update on strictly greater values.
    // This preserves the leftmost index when ties occur.
    for (i, &v) in arr.iter().enumerate().skip(1) {
        if v > best_val {
            best_val = v;
            best_idx = i;
        }
    }

    best_idx
}

fn main() {
    // Example usage
    let a = vec![3i8, 7, 7, -1];
    assert_eq!(argmax(&a), 1);

    let b = vec![-5i8];
    assert_eq!(argmax(&b), 0);

    let c = vec![1i8, 2, 3, 2, 3];
    assert_eq!(argmax(&c), 2);
}